import {getPack,putPack,installedIds,validateBytes} from './storage.mjs';
const $=id=>document.getElementById(id);const catalog=await fetch('catalog.json').then(r=>{if(!r.ok)throw Error('Catalog unavailable');return r.json()}).catch(e=>{notice(e.message,true);return {editions:[]}});
let installed=new Set(),pack=null,worker=null,activeId=null,loadTicket=0,requestId=0,offset=0,lastQuery='',lastMode='words',busy=false,readerSize=22;
const short={engwebp:'English',mal:'മലയാളം',hin2017:'हिन्दी',mar:'मराठी',tam2017:'தமிழ்',tel2017:'తెలుగు'};
function notice(message,error=false){$('notice').textContent=message;$('notice').classList.toggle('error',error)}
function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function renderLibrary(){const area=$('editions');area.replaceChildren();for(const e of catalog.editions){const card=element('div',undefined,'editionCard'+(e.id===activeId?' active':''));const top=element('div',undefined,'editionTop');top.append(element('strong',short[e.id]),element('span',installed.has(e.id)?'INSTALLED':'AVAILABLE','badge'));card.append(top,element('small',e.abbreviation+' · '+(e.bytes/1048576).toFixed(1)+' MB'));const b=element('button',busy?'Please wait…':installed.has(e.id)?'Read edition':'Install for offline');b.disabled=busy;b.onclick=()=>loadEdition(e.id);card.append(b);area.append(card)}}
async function refreshInstalled(){try{installed=new Set(await installedIds())}catch(e){notice('Local storage is unavailable: '+e.message,true)}renderLibrary()}
function setBusy(value){busy=value;$('searchButton').disabled=value||!pack;for(const id of ['book','chapter','previous','next'])$(id).disabled=value||!pack;renderLibrary()}
async function loadEdition(id){if(busy)return;const e=catalog.editions.find(e=>e.id===id);if(!e)return;const ticket=++loadTicket;setBusy(true);requestId++;worker?.terminate();worker=null;pack=null;notice('Opening '+e.language+'…');$('reader').setAttribute('aria-busy','true');
 try{let stored=await getPack(id),data;if(stored){try{data=await validateBytes(stored.bytes,e)}catch{notice('Stored edition failed verification. Reinstalling from the local package…')}}
 if(!data){notice('Installing '+e.language+' · checking the full pack before activation…');const r=await fetch(e.file,{cache:'no-store'});if(!r.ok)throw Error('Pack download failed ('+r.status+').');const bytes=await r.arrayBuffer();data=await validateBytes(bytes,e);await putPack({id,sha256:e.sha256,bytes,installedAt:new Date().toISOString()});installed.add(id)}
 if(ticket!==loadTicket)return;pack=data;activeId=id;try{localStorage.setItem('verseone2-last',id)}catch{}
 worker=new Worker('search-worker.mjs',{type:'module'});worker.onerror=()=>{notice('Search worker failed. Reload the application.',true);setBusy(false)};worker.onmessage=({data:d})=>{if(d.edition!==activeId)return;if(d.type==='ready'){setBusy(false);$('reader').setAttribute('aria-busy','false');populateBooks();showChapter(pack.books.find(b=>b.id==='JHN')?.id||pack.books[0].id,'3');notice(pack.language+' is installed and checksum-verified. Reading and search now use local data.');renderAttribution();return}if(d.requestId!==requestId)return;if(d.type==='error'){notice(d.message,true);return}if(d.type==='results')showResults(d.result,d.ms)};worker.postMessage({type:'load',pack});
 }catch(e){setBusy(false);$('reader').setAttribute('aria-busy','false');notice('Edition unavailable. '+e.message+' No replacement text was used.',true);renderLibrary()}}
function populateBooks(){const s=$('book');s.replaceChildren();for(const b of pack.books){const o=element('option',b.name+' · '+b.english);o.value=b.id;s.append(o)}}
function populateChapters(b,ch){$('chapter').replaceChildren();for(const c of b.chapters){const o=element('option',c.label);o.value=c.label;$('chapter').append(o)}$('chapter').value=ch}
function showChapter(id,ch){if(!pack)return;requestId++;lastQuery='';offset=0;$('more').hidden=true;const b=pack.books.find(b=>b.id===id);const c=b.chapters.find(c=>c.label===ch)||b.chapters[0];$('book').value=id;populateChapters(b,c.label);$('editionLabel').textContent=pack.language.toUpperCase()+' / '+pack.abbreviation;$('passageTitle').textContent=b.name+' '+c.label;$('passageMeta').textContent=b.english+' · '+c.verses.length+' source verse units · '+pack.validation.status.replace('-',' ');$('content').replaceChildren();$('content').lang=pack.lang;for(const v of c.verses)renderVerse(v);if(!busy)notice('Source numbering is preserved. Combined labels contain the full source passage.');$('previous').disabled=pack.books[0].id===id&&c===b.chapters[0];$('next').disabled=pack.books.at(-1).id===id&&c===b.chapters.at(-1)}
function renderVerse(v){const row=element('article',undefined,'verse');row.id='verse-'+v.label;for(const h of v.headings||[])row.append(element('div',h.text,'verseHead'));row.append(element('span',v.label,'verseNum'));row.append(element('p',v.text||'This source entry has no verse-body text. Nothing has been supplied in its place.',v.text?'verseText':'sourceEmpty'));if(v.notes?.length){const d=element('details'),s=element('summary','Source notes ('+v.notes.length+')');d.append(s);for(const n of v.notes)d.append(element('p',n.text));row.append(d)}if(v.text){const present=element('button','Present verse','presentVerse');present.onclick=()=>openPresentation(v);row.append(present)}$('content').append(row)}
function search(append=false){if(!worker||busy)return;const query=$('query').value.trim();if(!query)return;lastQuery=query;lastMode=document.querySelector('[name=mode]:checked').value;offset=append?offset+100:0;requestId++;$('more').disabled=true;notice('Searching the installed edition…');worker.postMessage({type:'search',requestId,query,mode:lastMode,offset})}
function showResults(result,ms){$('more').disabled=false;if(result.error){notice(result.error,true);$('more').hidden=true;return}if(result.kind==='reference'){const b=pack.books.find(b=>b.id===result.book);$('book').value=b.id;populateChapters(b,result.chapter);$('content').replaceChildren();for(const v of result.rows)renderVerse(v);$('passageTitle').textContent=b.name+' '+result.chapter+':'+result.rows[0].label+(result.rows.length>1?'–'+result.rows.at(-1).label:'');$('passageMeta').textContent=pack.abbreviation+' · exact source labels';$('more').hidden=true;notice('Reference found locally. Verse bridges are shown in full.');return}
 $('passageTitle').textContent='Search results';$('passageMeta').textContent=result.total+' matches in '+pack.abbreviation+' · '+ms.toFixed(1)+' ms search execution';if(offset===0)$('content').replaceChildren();if(!result.total)$('content').append(element('p','No matching words in this installed edition. Try another term or exact reference.','empty'));
 for(const r of result.rows){const b=element('button',undefined,'result');b.append(element('strong',r.bookName+' '+r.chapter+':'+r.label),element('p',r.text));b.onclick=()=>{showChapter(r.book,r.chapter);document.getElementById('verse-'+r.label)?.scrollIntoView({block:'center'})};$('content').append(b)}$('more').hidden=offset+result.rows.length>=result.total;notice('All '+pack.validation.books+' books searched locally. Results are limited to this edition.')}
function move(d){if(!pack)return;const idx=pack.books.findIndex(b=>b.id===$('book').value),b=pack.books[idx],ci=b.chapters.findIndex(c=>c.label===$('chapter').value);if(b.chapters[ci+d])showChapter(b.id,b.chapters[ci+d].label);else{const next=pack.books[idx+d];if(next)showChapter(next.id,d>0?next.chapters[0].label:next.chapters.at(-1).label)}}
function renderAttribution(){const f=$('attribution');f.replaceChildren(element('div',pack.title),element('div',pack.copyright));const a=element('a',pack.license);a.href=pack.licenseUrl;a.target='_blank';a.rel='noopener';f.append(a,document.createTextNode(' · '));const source=element('a','Original source');source.href=pack.source;source.target='_blank';source.rel='noopener';f.append(source,element('p','Presentation conversion only: whitespace consolidated; notes and headings separated; typography simplified. No wording intentionally changed. See the integrity report for source exceptions and verification limits.'))}
$('searchForm').onsubmit=e=>{e.preventDefault();search()};$('more').onclick=()=>search(true);$('book').onchange=()=>showChapter($('book').value,'1');$('chapter').onchange=()=>showChapter($('book').value,$('chapter').value);$('previous').onclick=()=>move(-1);$('next').onclick=()=>move(1);$('startEnglish').onclick=()=>loadEdition('engwebp');$('textSize').onclick=()=>{readerSize=readerSize===28?20:readerSize+2;document.documentElement.style.setProperty('--reading',readerSize+'px')};$('libraryToggle').onclick=()=>{const open=$('library').classList.toggle('open');$('libraryToggle').setAttribute('aria-expanded',String(open))};$('persist').onclick=async()=>{try{$('storageStatus').textContent=await navigator.storage?.persist?.()?'Persistent storage granted. Manual deletion can still remove downloads.':'Persistence not granted. Keep a backup and check readiness before services.'}catch(e){$('storageStatus').textContent=e.message}};
function connection(){$('connection').textContent=navigator.onLine?'● Online · local reading available':'● Offline · using installed data'}connection();window.addEventListener('online',connection);window.addEventListener('offline',connection);
if('serviceWorker'in navigator){navigator.serviceWorker.register('sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{$('shellStatus').textContent=navigator.serviceWorker.controller?'Application shell cached for offline use.':'Application cached. Reload once to activate offline launch.';navigator.serviceWorker.addEventListener('controllerchange',()=>{$('shellStatus').textContent='Application shell cached for offline use.'})}).catch(e=>{$('shellStatus').textContent='Offline launch unavailable: '+e.message})}
await refreshInstalled();let saved;try{saved=localStorage.getItem('verseone2-last')}catch{}if(saved&&installed.has(saved))loadEdition(saved);

// Single-screen church presentation, using unchanged source verse text.
let stageContext=null;
function openPresentation(v){if(!pack)return;const book=pack.books.find(b=>b.id===$('book').value),chapter=book?.chapters.find(c=>c.label===$('chapter').value);if(!chapter)return;const verses=chapter.verses.filter(x=>x.text);const index=verses.findIndex(x=>x.label===v.label);if(index<0)return;stageContext={book,chapter,verses,index,edition:pack};$('stageStatus').textContent='';renderStage();$('stage').showModal();}
function renderStage(){const {book,chapter,verses,index,edition}=stageContext;const v=verses[index];$('stageVerse').textContent=v.text;$('stageVerse').lang=edition.lang;$('stageRef').textContent=book.name+' '+chapter.label+':'+v.label+' · '+edition.abbreviation;$('stageCredit').textContent=edition.copyright;$('stageLicense').href=edition.licenseUrl;$('stageLicense').textContent=edition.license;$('stagePrev').disabled=index===0;$('stageNext').disabled=index===verses.length-1;}
function stepStage(d){if(!stageContext)return;const i=stageContext.index+d;if(i>=0&&i<stageContext.verses.length){stageContext.index=i;renderStage()}}
$('stagePrev').onclick=()=>stepStage(-1);$('stageNext').onclick=()=>stepStage(1);$('stageTheme').onclick=()=>$('stage').classList.toggle('light');$('stageClose').onclick=()=>$('stage').close();$('stageFull').onclick=async()=>{try{if(document.fullscreenElement){await document.exitFullscreen()}else if($('stage').requestFullscreen){await $('stage').requestFullscreen()}else{$('stageStatus').textContent='Fullscreen unavailable on this browser; presentation still works.'}}catch{$('stageStatus').textContent='Fullscreen unavailable on this browser; presentation still works.'}};
$('stage').addEventListener('close',()=>{if(document.fullscreenElement===$('stage'))document.exitFullscreen().catch(()=>{});stageContext=null});
$('stage').addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();stepStage(e.key==='ArrowRight'?1:-1)}});
